const A=C.adminActions, S2=C.adminSubmit, fix=k=>{ const f=modal.querySelector('form'); f.removeAttribute('data-form'); f.dataset.crmForm=k; };
const after=async(m,k)=>{ toast(m); modal.open&&modal.close(); reload(k); };
