A['crm-fin-jv']=async()=>{ showModal('Manual journal','Opening balances, accruals, depreciation, corrections. Debits must equal credits. Owner/accountant only; logged.',`<div class="form-grid">${field('Date','date','date',selectedDate)}${field('Narration (why)','memo','text','','required')}</div><div class="table-wrap"><table><thead><tr><th>Account code</th><th>Debit ₹</th><th>Credit ₹</th><th>Line note</th></tr></thead><tbody>${[0,1,2,3].map(i=>`<tr><td><input name="a${i}" list="fin-coa" placeholder="e.g. 1000"></td><td><input name="d${i}" type="number" step="0.01" min="0"></td><td><input name="c${i}" type="number" step="0.01" min="0"></td><td><input name="m${i}"></td></tr>`).join('')}</tbody></table></div><datalist id="fin-coa">${(F.cache['gl|'+selectedDate]?.accounts||[]).map(a=>`<option value="${esc(a.code)}">${esc(a.name)}</option>`).join('')}</datalist><input type="hidden" name="client_key" value="${key()}">`,'x','Post journal'); fix('fin-jv'); };
