A['crm-fin-acct']=async t=>{ const to=selectedDate,from=to.slice(0,8)+'01'; const r=await api(`/api/crm-gl-ledger?code=${t.dataset.code}&from=${from}&to=${to}`); showModal(esc(r.account.code+' '+r.account.name),'Opening '+rs(r.opening)+' · '+esc(from)+' → '+esc(to),table(['Date','Journal','Source','Memo','Debit','Credit','Balance'],r.rows.map(x=>`<tr><td>${esc(x.business_date)}</td><td>${esc(x.journal_no)}</td><td>${esc(x.source_type)} #${x.source_id||''}</td><td>${esc(x.memo||x.jmemo||'')}</td><td>${x.debit?rs(x.debit):''}</td><td>${x.credit?rs(x.credit):''}</td><td>${rs(x.running)}</td></tr>`),'No entries'),'x','Close'); fix('fin-close'); };
A['crm-fin-jview']=async t=>{ const r=await api('/api/crm-gl-journal?id='+t.dataset.id), j=r.journal; showModal(esc(j.journal_no),esc(j.business_date+' · '+j.source_type+' #'+(j.source_id||'')+' · '+(j.memo||'')+' · '+j.status),table(['Account','Debit','Credit','Note'],r.lines.map(l=>`<tr><td>${esc(l.code)} ${esc(l.name)}</td><td>${l.debit?rs(l.debit):''}</td><td>${l.credit?rs(l.credit):''}</td><td>${esc(l.memo||'')}</td></tr>`))+(j.source_type==='manual'&&j.status==='posted'&&me.user.role==='owner'?`<input type="hidden" name="id" value="${j.id}">${field('Reason to reverse (only if needed)','reason')}`:''),'x',j.source_type==='manual'&&j.status==='posted'&&me.user.role==='owner'?'Reverse journal':'Close'); fix(j.source_type==='manual'&&j.status==='posted'&&me.user.role==='owner'?'fin-jrev':'fin-close'); };
