A['crm-fin-daily']=async()=>{ const locs=(window.data?.crm?.kitchen?[]:[]); const d=selectedDate; const r=await api(`/api/crm-stock-movement?from=${d}&to=${d}&location_id=0`);
  const loc=r.locations; showModal('Daily stock register '+esc(d),'Opening · received · transfer in/out · used · waste · count adj. · closing',`<label class="field">Location <select id="fin-dloc"><option value="0">Whole restaurant</option>${loc.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><div id="fin-dreg">${regTable(r)}</div>${r.consistency.length?`<div class="fin-flag medium">⚠ ${r.consistency.length} item(s) whose location balances differ from the item total (legacy entries): ${r.consistency.map(c=>esc(c.name)).join(', ')}</div>`:''}`,'x','Close'); fix('fin-close'); };
